pathd_output=/home/lap_awlv/LTX-Video/outputs/inference-9/videos
mkdir -p $pathd_output

idx_prompt=0
for prompt in "${ls_prompts[@]}"; do
    echo "Prompt $idx_prompt: $prompt"

    CUDA_VISIBLE_DEVICES=2 python inference.py \
        --prompt "$prompt" \
        --num_frames 161 \
        --seed 42 \
        --pipeline_config configs/ltxv-13b-0.9.7-distilled.yaml \
        --output_path $pathd_output/$idx_prompt.mp4 \
        --frame_rate 16 \
        --height 1280 \
        --width 736 \
        # --conditioning_media_paths gen10.png \
        # --conditioning_start_frames 0 \
        # --offload_to_cpu \
    done
    idx_prompt=$((idx_prompt + 1))
    echo
done